package reference_test

import (
	"database/sql"
	"reflect"
	"testing"

	"stuntgres/reference/fixture"
)

func persistenceMetadataCase(t *testing.T) {
	fixture.RoleReferenceCleanup(t,[]string{"persistence_reader"})
	persistenceScenario(t,func(t *testing.T,p *fixture.Pair,b fixture.Backend,c *sql.Conn) {
		for _,q:=range []string{
			"CREATE ROLE persistence_reader",
			"CREATE UNLOGGED TABLE metadata_t(id serial PRIMARY KEY,n int GENERATED BY DEFAULT AS IDENTITY,note text DEFAULT 'keep',derived int GENERATED ALWAYS AS(id+1) STORED)",
			"ALTER TABLE metadata_t ADD CONSTRAINT positive CHECK(id>0)",
			"ALTER TABLE metadata_t ADD CONSTRAINT self_fk FOREIGN KEY(id) REFERENCES metadata_t(id)",
			"CREATE INDEX metadata_note ON metadata_t(note)",
			"ALTER TABLE metadata_t ENABLE ROW LEVEL SECURITY",
			"ALTER TABLE metadata_t FORCE ROW LEVEL SECURITY",
			"GRANT SELECT ON metadata_t TO persistence_reader",
			"GRANT UPDATE(note) ON metadata_t TO persistence_reader",
			"COMMENT ON TABLE metadata_t IS 'table-comment'",
			"COMMENT ON COLUMN metadata_t.note IS 'column-comment'",
			"COMMENT ON SEQUENCE metadata_t_id_seq IS 'sequence-comment'",
			"ALTER SEQUENCE metadata_t_id_seq INCREMENT 3 CACHE 1 MINVALUE 1 MAXVALUE 1000 START 10 RESTART 10",
		} {persistenceExec(t,p,b,c,q)}
		persistenceRun(t,p,b,c,fixture.Exec("INSERT INTO metadata_t DEFAULT VALUES",1))
		queries:=[]string{
			"SELECT oid::bigint,relname,reltype::bigint,relowner::bigint,relacl::text,relrowsecurity,relforcerowsecurity,obj_description(oid,'pg_class') FROM pg_class WHERE relname IN('metadata_t','metadata_t_pkey','metadata_note','metadata_t_id_seq','metadata_t_n_seq') ORDER BY relname",
			"SELECT attnum,attname,atttypid::bigint,atttypmod,attnotnull,attidentity,attgenerated,attacl::text,col_description(attrelid,attnum) FROM pg_attribute WHERE attrelid='metadata_t'::regclass AND attnum>0 ORDER BY attnum",
			"SELECT oid::bigint,conname,contype,convalidated,conenforced,conindid::bigint,pg_get_constraintdef(oid),obj_description(oid,'pg_constraint') FROM pg_constraint WHERE conrelid='metadata_t'::regclass ORDER BY conname",
			"SELECT adnum,pg_get_expr(adbin,adrelid) FROM pg_attrdef WHERE adrelid='metadata_t'::regclass ORDER BY adnum",
			"SELECT seqrelid::bigint,seqtypid::bigint,seqstart,seqincrement,seqmax,seqmin,seqcache,seqcycle FROM pg_sequence WHERE seqrelid IN('metadata_t_id_seq'::regclass,'metadata_t_n_seq'::regclass) ORDER BY seqrelid",
			// TOAST relations have physical rewrite identities, not logical SQL
			// dependency identity. Keep every non-TOAST relation dependency.
			"SELECT d.classid::bigint,d.objid::bigint,d.objsubid,d.refclassid::bigint,d.refobjid::bigint,d.refobjsubid,d.deptype FROM pg_depend d JOIN pg_class dependent ON dependent.oid=d.objid WHERE d.refobjid='metadata_t'::regclass AND d.classid='pg_class'::regclass AND dependent.relkind<>'t' ORDER BY d.objid,d.objsubid,d.deptype",
		}
		capture:=func(query string) [][]any {
			rows,err:=c.QueryContext(p.Ctx,query);if err!=nil {t.Fatal(err)};defer rows.Close()
			columns,err:=rows.Columns();if err!=nil {t.Fatal(err)}
			var result [][]any
			for rows.Next() {
				values:=make([]any,len(columns));dest:=make([]any,len(columns));for i:=range values {dest[i]=&values[i]}
				if err=rows.Scan(dest...);err!=nil {t.Fatal(err)}
				for i:=range values {values[i]=fixture.Normalize(values[i])}
				result=append(result,values)
			}
			if err=rows.Err();err!=nil {t.Fatal(err)}
			if len(result)==0 {t.Fatal("empty metadata witness",query)}
			return result
		}
		before:=make([][][]any,len(queries));for i,q:=range queries {before[i]=capture(q)}
		for _,mode:=range []string{"LOGGED","UNLOGGED"} {
			persistenceExec(t,p,b,c,"ALTER TABLE metadata_t SET "+mode)
			for i,q:=range queries {if got:=capture(q);!reflect.DeepEqual(got,before[i]) {t.Fatalf("metadata changed: %s\ngot %#v\nwant %#v",q,got,before[i])}}
			persistenceRun(t,p,b,c,fixture.Select("SELECT id,n,note,derived FROM metadata_t",[]string{"id","n","note","derived"},[]string{"INT4","INT4","TEXT","INT4"},[][]any{{int64(10),int64(1),"keep",int64(11)}}))
			persistenceRun(t,p,b,c,fixture.Select("SELECT relrowsecurity,relforcerowsecurity,obj_description(oid,'pg_class') AS comment FROM pg_class WHERE oid='metadata_t'::regclass",[]string{"relrowsecurity","relforcerowsecurity","comment"},[]string{"BOOL","BOOL","TEXT"},[][]any{{true,true,"table-comment"}}))
		}
	})
}
